    # Step 2: Keep only dense colors (>6 occurrences)
    dense_colors = {c for c, cnt in color_counts.items() if cnt > 6}
    print(f"Dense colors to keep: {dense_colors}")

    output = []
    for r in range(len(grid)):
        row = []
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val == bg or val not in dense_colors:
                row.append(bg)
            else:
                row.append(val)
        output.append(row)

    # Step 3: Crop trailing empty rows
    while output and all(cell == bg for cell in output[-1]):
        output.pop()

    # Step 4: Crop trailing empty columns
    while output and len(output[0]) > 0 and all(row[-1] == bg for row in output):
