# Check fill ratios more precisely
def analyze_fill_ratio(grid, bg):
    from collections import defaultdict
    result = {}
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            v = int(grid[r][c]) if not isinstance(grid[r][c], int) else grid[r][c]
            if v != bg:
                if v not in result:
                    result[v] = {'positions': [], 'min_r': float('inf'), 'max_r': 0, 
                                  'min_c': float('inf'), 'max_c': 0}
                pos = (r, c)
                result[v]['positions'].append(pos)
                result[v]['min_r'] = min(result[v]['min_r'], r)
                result[v]['max_r'] = max(result[v]['max_r'], r)
                result[v]['min_c'] = min(result[v]['min_c'], c)
                result[v]['max_c'] = max(result[v]['max_c'], c)

    analysis = {}
    for v, data in sorted(result.items()):
        total_px = len(data['positions'])
        bbox_h = data['max_r'] - data['min_r'] + 1
        bbox_w = data['max_c'] - data['min_c'] + 1
        bbox_area = bbox_h * bbox_w
        fill = total_px / bbox_area
        analysis[v] = {
            'pixels': total_px,
            'bbox': f"{bbox_h}x{bbox_w}",
            'area': bbox_area,
            'fill_ratio': round(fill, 3),
            'is_perfect_rect': fill == 1.0
        }
    return analysis

