# Analyze connected components for demo inputs
def analyze_grid_components(grid_str, bg_val):
    h = len(grid_str)
    visited = set()
    components_by_color = {}

    positions_by_color = {}
    for r in range(h):
        for c in range(len(grid_str[r])):
            val = int(grid_str[r][c]) if isinstance(grid_str[r][c], str) else grid_str[r][c]
            if val == bg_val or val not in positions_by_color:
                continue
            if val not in positions_by_color:
                positions_by_color[val] = []
            positions_by_color[val].append((r, c))

    # Find components for each color
    for color, pos_list in positions_by_color.items():
        comp_counter = {}
        for cr, cc in pos_list:
            key = (cr, cc)
            if key not in visited:
                comp_size = 0
                local_visited = {key}
                queue = [(cr, cc)]
                while queue:
                    r, c = queue.pop(0)
                    local_key = (r, c)
                    if local_key not in visited:
                        visited.add(local_key)
                        comp_size += 1
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = r+dr, c+dc
                            nkey = (nr, nc)
                            if 0 <= nr < h and 0 <= nc < len(grid_str[nr]):
                                nval = int(grid_str[nr][nc]) if isinstance(grid_str[nr][nc], str) else grid_str[nr][nc]
                                if nval == color and nkey not in local_visited:
                                    local_visited.add(nkey)
                                    queue.append((nr, nc))
                comp_counter[comp_size] = comp_counter.get(comp_size, 0) + 1

        num_comps = len(comp_counter)
        sizes = list(comp_counter.keys())
        avg_size = sum(sizes) / len(sizes) if sizes else 0
        max_size = max(sizes) if sizes else 0
        all_singletons = all(s == 1 for s in sizes)

        components_by_color[color] = {
            'total_pixels': sum(comp_counter.values()),
            'num_comps': num_comps,
            'sizes': sorted(sizes),
            'avg_size': avg_size,
            'max_size': max_size,
            'all_singletons': all_singletons
        }

    return components_by_color

